using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Reporting;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class ReportingRepository(SqlConnectionFactory f):IReportingRepository{public async Task<ReportSummaryDto>GetSummaryAsync(ReportQuery q,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);var from=q.From??DateTime.UtcNow.Date.AddDays(-30);var to=q.To??DateTime.UtcNow;await using var cmd=new SqlCommand("SELECT COALESCE(SUM(GrandTotal),0),COALESCE(SUM(TaxTotal),0),COUNT(1) FROM Sales WHERE IsDeleted=0 AND CreatedAtUtc>=@F AND CreatedAtUtc<@T;SELECT COALESCE(SUM(GrandTotal),0),COALESCE(SUM(TaxTotal),0),COUNT(1) FROM Purchases WHERE IsDeleted=0 AND CreatedAtUtc>=@F AND CreatedAtUtc<@T;SELECT COALESCE(SUM(Stock*PurchasePrice),0) FROM Medicines WHERE IsDeleted=0;SELECT TOP 5 MedicineName,SUM(Quantity),SUM(LineTotal),SUM(LineTotal)-SUM(Quantity*UnitPrice) FROM SaleItems si JOIN Sales s ON s.Id=si.SaleId WHERE s.IsDeleted=0 AND s.CreatedAtUtc>=@F AND s.CreatedAtUtc<@T GROUP BY MedicineName ORDER BY SUM(Quantity) DESC",c);cmd.Parameters.AddWithValue("@F",from);cmd.Parameters.AddWithValue("@T",to);await using var r=await cmd.ExecuteReaderAsync(ct);await r.ReadAsync(ct);var sales=r.GetDecimal(0);var outGst=r.GetDecimal(1);await r.NextResultAsync(ct);await r.ReadAsync(ct);var purchases=r.GetDecimal(0);var inGst=r.GetDecimal(1);await r.NextResultAsync(ct);await r.ReadAsync(ct);var stock=r.GetDecimal(0);await r.NextResultAsync(ct);var top=new List<ReportMedicineDto>();while(await r.ReadAsync(ct))top.Add(new(r.GetString(0),r.GetInt32(1),r.GetDecimal(2),r.GetDecimal(2)-r.GetInt32(1)*0));return new(sales,purchases,sales-purchases,stock,outGst,inGst,top);}public async Task<ComplianceSummaryDto>GetComplianceAsync(ReportQuery q,CancellationToken ct){var x=await GetSummaryAsync(q,ct);return new(x.TotalSales-x.OutputGst,x.OutputGst,x.InputGst,x.OutputGst-x.InputGst,x.TopMedicines.Count,0);}}

